//! Library surface for op-xray-daemon — exposed so throwaway examples/tests
//! can dial the commander client directly without spawning the D-Bus daemon.

pub mod commander_client;

//! Xray D-Bus Daemon
//!
//! Provides D-Bus interfaces for managing the Xray proxy daemon lifecycle.
//! Replaces direct subprocess spawning with a schema-driven D-Bus service.
//!
//! D-Bus object path: /org/opdbus/v1/plugins/xray
//! Interface: opdbus.v1.Xray
//!
//! ## Architecture
//!
//! Per AGENTS.md D-Bus-first rules:
//! - All xray control operations go through D-Bus methods
//! - Xray's live config path is /etc/xray/xray_config.json inside the container
//! - No direct Command::new("xray") spawning - use D-Bus service instead
//!
//! ## Methods
//! - start(config_path) -> (bool, String)
//! - stop() -> (bool, String)
//! - restart(config_path) -> (bool, String)
//! - status() -> JSON string
//! - reload() -> (bool, String)
//! - get_config() -> String

use anyhow::{Context, Result};
use tokio::signal;
use tracing::info;
use zbus::connection::Connection;

mod dbus;
use dbus::XrayService;
use op_xray_daemon::commander_client;

/// CLI arguments
#[derive(Debug, Clone)]
struct Args {
    /// Initial config path to use on startup
    config_path: Option<String>,
}

impl Args {
    fn parse() -> Self { … }
}

/// Canonical live config path inside the Xray container.
const DEFAULT_CONFIG_PATH: &str = "/etc/xray/xray_config.json";

#[tokio::main]
async fn main() -> Result<()> { … }

//! D-Bus service implementation for Xray daemon management
//!
//! Provides the `org.opdbus.v1.Xray` interface for controlling
//! xray process lifecycle via D-Bus.
//!
//! Production xray runs under the `xray` container's own systemd
//! (`xray.service`), not spawned by this daemon — `start()` here predates
//! that and is effectively unsupported now (see its doc comment). Liveness
//! is detected by scanning `/proc` for the real process, not by tracking a
//! child handle this daemon itself spawned — the previous in-memory
//! `Option<Child>` tracking lost all state across a daemon restart and could
//! never see an externally-started xray process at all, which is the
//! process this daemon actually needs to observe in practice.

use serde::{Deserialize, Serialize};
…
use zbus::interface;

/// Status information for the Xray daemon
#[derive(Debug, Clone, Serialize, Deserialize)]
struct XrayStatus { … }

/// Find running `xray` process PIDs by scanning `/proc` directly — no
/// `pgrep`/`pkill` subprocess spawning (CLAUDE.md: no `Command::new(...)`
/// subprocesses in plugin/service code).
fn find_xray_pids() -> Vec<nix::unistd::Pid> { … }

/// Last config path this daemon was told about via `start()`/`restart()`
/// (informational only — a real xray process is detected live via `/proc`,
/// this is just the daemon's own last-instruction memory).
pub struct XrayProcessState {
    config_path: Option<String>,
}

impl XrayProcessState { … }

/// D-Bus service for managing Xray daemon lifecycle
pub struct XrayService {
    state: Arc<Mutex<XrayProcessState>>,
}

impl XrayService { … }

impl Default for XrayService { … }

/// D-Bus interface implementation for org.opdbus.v1.Xray
#[interface(name = "org.opdbus.v1.Xray")]
impl XrayService { … }

#[cfg(test)]
mod tests { … }

//! Client for xray-core's own commander API (StatsService/RoutingService/
//! LoggerService/HandlerService), dialed over the Unix socket xray binds
//! when `api.listen` is configured in its JSON config. See proto/VENDORED.md
//! for exact source provenance.
//!
//! This is unrelated to `org.opdbus.v1.Xray` (this daemon's own D-Bus
//! surface, which only manages the xray *process* lifecycle) — it talks
//! directly to the running xray-core binary's control plane.

use anyhow::{Context, Result};
…
use tower::service_fn;

// Generated cross-package references (e.g. RoutingService's use of
// xray.common.serial.TypedMessage) assume the Rust module tree mirrors the
// proto package tree exactly — hence the nesting here, not flat modules.
pub mod xray { … }

pub use xray::app::log::command as logger;
…
pub use xray::app::stats::command as stats;

/// Default path xray's commander API socket binds to. Bind-mounted out of
/// the `xray` container via the existing `opdbus-rt` disk device (so this
/// path resolves the same from the host, where op-xray-daemon itself runs,
/// and from inside the container, where xray-core actually creates it) —
/// see the `api-in` inbound in the `xray` container's `xray_config.json`.
///
/// NOTE: `/run/...` (the FHS-correct location, matching every other socket
/// in this repo — `/run/opdbus`, `/run/ghostbridge`, etc.) was tried first
/// and is where this belongs. It didn't work: a fresh `disk` device at
/// `/run/xray` never actually attached to this container even after a full
/// `incus restart` (mounted as the container's own tmpfs instead) — and the
/// already-configured `opdbus-sock` device (`/run/opdbus`) has the exact
/// same problem, so this isn't specific to the new device. That's a
/// pre-existing container/incus mount-ordering issue, separate from this
/// task. `/var/lib/opdbus-runtime` is used here only because it's the one
/// bind mount confirmed to actually work on this container.
pub const DEFAULT_API_SOCKET: &str = "/var/lib/opdbus-runtime/xray-api-socket/api.sock";

async fn connect_uds(path: String) -> std::io::Result<tokio::net::UnixStream> {
    tokio::net::UnixStream::connect(path).await
}

/// Open a gRPC channel to xray's commander API over its Unix socket.
pub async fn connect(socket_path: &str) -> Result<Channel> { … }

/// HandlerService shares the existing container commander socket. It must be
/// enabled by the prepared Xray configuration; connection/Unimplemented errors
/// are propagated rather than modifying that configuration or reloading Xray.
pub async fn handler_client(
    socket_path: &str,
    timeout: std::time::Duration,
) -> Result<handler::handler_service_client::HandlerServiceClient<Channel>> { … }

pub async fn stats_client(
    socket_path: &str,
) -> Result<stats::stats_service_client::StatsServiceClient<Channel>> { … }

pub async fn routing_client(
    socket_path: &str,
) -> Result<router::routing_service_client::RoutingServiceClient<Channel>> { … }

pub async fn logger_client(
    socket_path: &str,
) -> Result<logger::logger_service_client::LoggerServiceClient<Channel>> { … }

